import Modes from '@config/modes';
import {logger, LogTypes} from '@lib/logger';
import MTPNetworker from '@lib/mtproto/networker';
import Obfuscation from '@lib/mtproto/transports/obfuscation';
import MTTransport, {MTConnection, MTConnectionConstructable} from '@lib/mtproto/transports/transport';
// import intermediatePacketCodec from '@lib/mtproto/transports/intermediate';
import abridgedPacketCodec from '@lib/mtproto/transports/abridged';
// import paddedIntermediatePacketCodec from '@lib/mtproto/transports/padded';
import {ConnectionStatus} from '@lib/mtproto/connectionStatus';
import transportController from '@lib/mtproto/transports/controller';
import bytesToHex from '@helpers/bytes/bytesToHex';
// import networkStats from '@lib/mtproto/networkStats';
import ctx from '@environment/ctx';
import {applySocketUrl, getActiveFront, noteFrontFailed, subscribeProxyRoute} from '@lib/mtproto/proxyRoute';
import {wakeProxySearch} from '@lib/mtproto/proxyAutoSelector';

export default class TcpObfuscated implements MTTransport {
  private codec = abridgedPacketCodec;
  private obfuscation = new Obfuscation();
  public networker: MTPNetworker;

  private pending: Array<Partial<{
    resolve: any,
    reject: any,
    body: Uint8Array,
    bodySent: boolean
  }>> = [];

  private debug = Modes.debug && false/* true */;
  private log: ReturnType<typeof logger>;
  public connected = false;
  private lastCloseTime: number;
  public connection: MTConnection;

  private autoReconnect = true;
  private reconnectTimeout: number;
  private releasingPending: boolean;
  private unsubscribeRoute: () => void;
  private sawMessage = false;
  private proven = false;
  private reopenMisses = 0;
  private handshakeSent = false;
  private connectionGeneration = 0;
  private stallTimer: number;
  private onClose: () => void = () => {};
  private readyInit: Promise<Uint8Array>;
  private readonly stallMs = 8000;
  private readonly silenceMs = 25000;

  // private debugPayloads: MTPNetworker['debugRequests'] = [];

  constructor(
    private Connection: MTConnectionConstructable,
    private dcId: number,
    private url: string,
    private logSuffix: string,
    private retryTimeout: number
  ) {
    let logTypes = LogTypes.Error | LogTypes.Log;
    if(this.debug) logTypes |= LogTypes.Debug;
    this.log = logger(`TCP-${dcId}` + logSuffix, logTypes);
    this.log('constructor');

    this.unsubscribeRoute = subscribeProxyRoute(() => {
      const next = applySocketUrl(this.dcId, this.url);
      if(!next) {
        if(this.connection) this.close();
        return;
      }
      if(!this.connection || next !== this.url) this.changeUrl(next);
    });

    this.connect();
  }

  private onOpen = async() => {
    const generation = this.connectionGeneration;
    this.connected = true;
    this.clearStall();

    if(import.meta.env.VITE_MTPROTO_AUTO && Modes.multipleTransports) {
      transportController.setTransportOpened('websocket');
    }

    const initPayload = await (this.readyInit || this.obfuscation.init(this.codec));
    if(generation !== this.connectionGeneration || !this.connected) {
      return;
    }

    this.connection.send(initPayload);
    this.handshakeSent = true;

    if(this.networker) {
      this.pending.length = 0; // ! clear queue and reformat messages to container, because if sending simultaneously 10+ messages, connection will die
      this.networker.onTransportOpen();
    }

    setTimeout(() => {
      this.releasePending();
    }, 0);
    if(!this.logSuffix) this.armSilence(generation, this.url);
  };

  private onMessage = async(buffer: ArrayBuffer) => {
    // networkStats.addReceived(this.dcId, buffer.byteLength);
    this.sawMessage = true;
    if(!this.logSuffix) {
      this.proven = true;
      this.reopenMisses = 0;
    }
    this.clearStall();

    const time = Date.now();
    let data = await this.obfuscation.decode(new Uint8Array(buffer));
    data = this.codec.readPacket(data);

    if(this.networker) { // authenticated!
      // this.pending = this.pending.filter((p) => p.body); // clear pending

      this.networker.onTransportData(data, time);

      // this.dd();
      return;
    }

    // console.log('got hex:', data.hex);
    const pending = this.pending.shift();
    if(!pending) {
      this.debug && this.log.debug('no pending for res:', bytesToHex(data));
      return;
    }

    pending.resolve(data);
  };

  private retireFront(openedUrl: string) {
    // File sockets miss on purpose on some fronts. Only the chat socket retires one.
    if(this.logSuffix || !this.autoReconnect) return;
    const front = getActiveFront();
    if(front && openedUrl.includes(`.${front}/`)) noteFrontFailed();
  }

  private clearStall() {
    if(this.stallTimer !== undefined) {
      clearTimeout(this.stallTimer);
      this.stallTimer = undefined;
    }
  }

  /**
   * Only a socket that never opens is failed over, and not quickly: a mobile
   * radio often needs more than a few seconds. An open socket is left alone
   * until it has been silent for a long time.
   */
  private armStall(generation: number, openedUrl: string) {
    this.clearStall();
    const wait = this.proven && !this.logSuffix ? 4000 : this.stallMs;
    this.stallTimer = ctx.setTimeout(() => {
      this.stallTimer = undefined;
      if(generation !== this.connectionGeneration || this.sawMessage || this.connected) return;
      if(!this.autoReconnect) return;
      this.failOrRetry(generation, openedUrl);
    }, wait);
  }

  private armSilence(generation: number, openedUrl: string) {
    this.clearStall();
    this.stallTimer = ctx.setTimeout(() => {
      this.stallTimer = undefined;
      if(generation !== this.connectionGeneration || this.sawMessage) return;
      if(!this.autoReconnect) return;
      this.failOrRetry(generation, openedUrl);
    }, this.silenceMs);
  }

  /** A front that already worked is opened again at once. Only a second miss gives it up. */
  private failOrRetry(generation: number, openedUrl: string) {
    if(this.proven && !this.logSuffix && this.reopenMisses < 1) {
      this.reopenMisses++;
      this.forceReconnect();
      return;
    }

    this.retireFront(openedUrl);
    if(generation !== this.connectionGeneration || this.sawMessage) return;
    this.forceReconnect();
  }

  private finishClose(openedUrl: string) {
    const shouldRetire = !this.proven && !this.sawMessage && (this.handshakeSent || !this.connected);
    this.clear();
    if(shouldRetire) this.retireFront(openedUrl);
    if(!this.logSuffix && !getActiveFront()) wakeProxySearch();
    const replaced = !!this.connection;

    let needTimeout = 0;
    let retryAt: number | undefined;
    if(this.autoReconnect) {
      const time = Date.now();
      const diff = time - this.lastCloseTime;
      needTimeout = !isNaN(diff) && diff < this.retryTimeout ? this.retryTimeout - diff : 0;
      if(this.proven && !this.logSuffix) needTimeout = 0;
      retryAt = time + needTimeout;
    }

    // An immediate reopen is already starting. A Closed status with a timer
    // would sit on screen until that timer, on top of the new socket.
    if(this.networker && !replaced && !(this.autoReconnect && needTimeout === 0)) {
      this.networker.setConnectionStatus(ConnectionStatus.Closed, retryAt);
      this.pending.length = 0;
    }

    if(replaced) return;

    if(!this.autoReconnect) {
      this.log('reconnect isn\'t needed');
      return;
    }

    if(needTimeout) {
      this.log('will try to reconnect after timeout:', needTimeout / 1000);
      this.reconnectTimeout = ctx.setTimeout(this.reconnect, needTimeout);
      return;
    }

    this.reconnect();
  }

  public clear() {
    if(import.meta.env.VITE_MTPROTO_AUTO && Modes.multipleTransports) {
      if(this.connected) {
        transportController.setTransportClosed('websocket');
      }
    }

    this.connected = false;
    this.clearStall();

    if(this.connection) {
      this.connection.removeEventListener('open', this.onOpen);
      this.connection.removeEventListener('close', this.onClose);
      this.connection.removeEventListener('message', this.onMessage);
      this.connection = undefined;
    }
  }

  /**
   * invoke only when closed
   */
  public reconnect = () => {
    if(this.reconnectTimeout !== undefined) {
      clearTimeout(this.reconnectTimeout);
      this.reconnectTimeout = undefined;
    }

    if(this.connection) {
      return;
    }

    this.log('trying to reconnect...');
    this.lastCloseTime = Date.now();

    if(!this.networker) {
      for(const pending of this.pending) {
        if(pending.bodySent) {
          pending.bodySent = false;
        }
      }
    } else {
      this.networker.setConnectionStatus(ConnectionStatus.Connecting);
    }

    this.connect();
  }

  /**
   * Ask the browser to close. If it never reports the close, open the same
   * front again. A new search is not started: that was replacing a live chat.
   */
  public closeOrReplace() {
    const generation = this.connectionGeneration;
    try {
      this.connection?.close();
    } catch{ /* already gone */ }

    ctx.setTimeout(() => {
      if(generation !== this.connectionGeneration) return;
      this.forceReconnect();
    }, this.proven && !this.logSuffix ? 2000 : 10000);
  }

  public forceReconnect() {
    this.close();
    this.reconnect();
  }

  public destroy() {
    this.unsubscribeRoute?.();
    this.unsubscribeRoute = undefined;
    this.setAutoReconnect(false);
    this.close();

    if(this.obfuscation) {
      this.obfuscation.destroy();
    }

    this.pending.forEach((pending) => {
      if(pending.reject) {
        pending.reject();
      }
    });
    this.pending.length = 0;
  }

  public close() {
    const connection = this.connection;
    if(connection) {
      const connected = this.connected;
      this.clear();
      if(connected) { // wait for buffered messages if they are there
        connection.addEventListener('message', this.onMessage);
        connection.addEventListener('close', () => {
          connection.removeEventListener('message', this.onMessage);
        }, {once: true});
      }
      // A socket that has not opened yet must still be closed. Leaving it
      // in CONNECTING piles up until the browser stops opening new ones,
      // and the chat then stays on "Reconnecting" for good.
      connection.close();
    }
  }

  /**
   * Will connect if enable and disconnected \
   * Will reset reconnection timeout if disable
   */
  public setAutoReconnect(enable: boolean) {
    this.autoReconnect = enable;

    if(!enable) {
      this.clearStall();
      if(this.reconnectTimeout !== undefined) {
        clearTimeout(this.reconnectTimeout);
        this.reconnectTimeout = undefined;
      }
    } else if(!this.connection && this.reconnectTimeout === undefined) {
      this.reconnect();
    }
  }

  private connect() {
    this.sawMessage = false;
    this.handshakeSent = false;
    if(this.connection) {
      this.close();
    }

    const next = applySocketUrl(this.dcId, this.url);
    // No proven front yet. Opening web.telegram.org here stays silent without
    // a VPN and the chat never leaves it.
    if(!next) {
      this.log('waiting for a front');
      return;
    }
    this.url = next;

    const generation = ++this.connectionGeneration;
    const openedUrl = this.url;
    this.readyInit = this.obfuscation.init(this.codec);
    this.onClose = () => {
      if(generation !== this.connectionGeneration) return;
      this.finishClose(openedUrl);
    };

    this.connection = new this.Connection(this.dcId, this.url, this.logSuffix);
    this.connection.addEventListener('open', this.onOpen);
    this.connection.addEventListener('close', this.onClose);
    this.connection.addEventListener('message', this.onMessage);
    this.armStall(generation, openedUrl);
  }

  public changeUrl(url: string) {
    if(!url || (this.url === url && this.connection)) {
      return;
    }

    this.url = url;
    this.forceReconnect();
  }

  private encodeBody(body: Uint8Array) {
    const toEncode = this.codec.encodePacket(body);

    // this.log('send before obf:', /* body.hex, nonce.hex, */ toEncode.hex);
    const encoded = this.obfuscation.encode(toEncode);
    // this.log('send after obf:', enc.hex);

    return encoded;
  }

  public send(body: Uint8Array) {
    this.debug && this.log.debug('-> body length to pending:', body.length);

    if(this.networker) {
      this.pending.push({body});
      this.releasePending();
    } else {
      const promise = new Promise<typeof body>((resolve, reject) => {
        this.pending.push({resolve, reject, body});
      });

      this.releasePending();

      return promise;
    }
  }

  private async releasePending(/* tt = false */) {
    if(!this.connected || this.releasingPending) {
      // this.connect();
      return;
    }

    this.releasingPending = true;
    // * the obfuscation is keyed anew for every connection: what is encoded here is for this one only
    const connection = this.connection;

    /* if(!tt) {
      this.releasePendingDebounced();
      return;
    } */

    // this.log('-> messages to send:', this.pending.length);
    let length = this.pending.length;
    let sent = false;
    // for(let i = length - 1; i >= 0; --i) {
    for(let i = 0; i < length; ++i) {
      const pending = this.pending[i];
      if(!pending) {
        break;
      }

      const {body, bodySent} = pending;
      if(body && !bodySent) {
        // this.debugPayloads.push({before: body.slice(), after: enc});

        this.debug && this.log.debug('-> body length to send:', body.length);

        // * encoded every time it goes, never kept: a plain request is sent again after a
        // * reconnect, and bytes of the previous connection read as noise on the next one
        const encoded = await this.encodeBody(body);
        if(!this.connected || this.connection !== connection) {
          break;
        }

        // networkStats.addSent(this.dcId, encoded.byteLength);
        this.connection.send(encoded);

        if(!pending.resolve) { // remove if no response needed
          this.pending.splice(i--, 1);
          length--;
        } else {
          pending.bodySent = true;
        }

        sent = true;
        // delete pending.body;
      }
    }

    this.releasingPending = undefined;

    // * a connection that opened meanwhile found the queue busy and left it to this run
    if(this.pending.length && (sent || this.connection !== connection)) {
      this.releasePending();
    }
  }
}
